import { useCallback, useEffect, useState, type FormEvent, type ReactNode } from 'react'
import { Activity, BarChart3, Bell, BookOpen, CalendarDays, Check, ChevronLeft, ChevronRight, ClipboardList, FileSpreadsheet, FolderKanban, GraduationCap, LayoutDashboard, LogOut, Menu, Plus, Search, Settings, Shield, Sparkles, Upload, Users, X } from 'lucide-react'
import { z } from 'zod'
import { apiRequest, ApiError, signOut, type AcademicYear, type ApiPage, type DashboardSummary, type Project, type ProjectOptions, type Role, type Student, type StudentProfile as StudentProfileData, type StudentProject, type UserProfile } from './lib/api'
import { AuthScreen } from './components/AuthScreen'
import { Reports } from './components/Reports'
import './App.css'

type Screen = 'dashboard' | 'reports' | 'students' | 'projects' | 'new-project' | 'project-detail' | 'imports' | 'users' | 'notifications' | 'student-profile' | 'years' | 'account'
type Toast = { type: 'success' | 'error'; message: string }
const navItems: Array<{ id: Screen; label: string; icon: typeof LayoutDashboard; admin?: boolean }> = [
  { id: 'dashboard', label: 'Genel Bakış', icon: LayoutDashboard },
  { id: 'reports', label: 'Raporlama', icon: BarChart3 },
  { id: 'students', label: 'Öğrenciler', icon: GraduationCap },
  { id: 'projects', label: 'Projeler', icon: FolderKanban },
  { id: 'new-project', label: 'Proje Oluştur', icon: Plus },
  { id: 'imports', label: 'Excel Aktarımı', icon: FileSpreadsheet, admin: true },
  { id: 'users', label: 'Kullanıcı Yönetimi', icon: Users, admin: true },
  { id: 'years', label: 'Akademik Yıllar', icon: CalendarDays, admin: true },
  { id: 'notifications', label: 'Bildirimler', icon: Bell },
  { id: 'account', label: 'Hesap ayarları', icon: Settings },
]
const dateLabel = (value?: string | Date | null) => value ? new Intl.DateTimeFormat('tr-TR', { dateStyle: 'medium' }).format(new Date(value)) : '—'
const personName = (firstName: string, lastName: string) => `${firstName.trim()} ${lastName.trim()}`.trim()

export function App() {
  const [user, setUser] = useState<UserProfile | null>(null)
  const [booting, setBooting] = useState(true)
  const [screen, setScreen] = useState<Screen>('dashboard')
  const [selectedStudent, setSelectedStudent] = useState<string | null>(null)
  const [selectedProject, setSelectedProject] = useState<string | null>(null)
  const [toast, setToast] = useState<Toast | null>(null)
  const [mobileNav, setMobileNav] = useState(false)
  const [refreshKey, setRefreshKey] = useState(0)
  const refresh = () => setRefreshKey((n) => n + 1)
  const notify = (message: string, type: Toast['type'] = 'success') => { setToast({ message, type }); window.setTimeout(() => setToast(null), 4500) }
  useEffect(() => { apiRequest<UserProfile>('/api/me').then(setUser).catch(() => setUser(null)).finally(() => setBooting(false)) }, [])
  if (booting) return <div className="boot-screen"><div className="brand-mark">Ü</div><span>Güvenli oturum kontrol ediliyor…</span></div>
  if (!user) return <AuthScreen onAuthenticated={setUser} />
  if (user.mustChangePassword) return <PasswordGate user={user} onChanged={() => setUser({ ...user, mustChangePassword: false })} />
  const visibleNav = navItems.filter((item) => !item.admin || user.role === 'ADMIN')
  const titles: Record<Screen, string> = { dashboard: 'Genel Bakış', reports: 'Raporlama ve Analiz', students: 'Öğrenciler', projects: 'Projeler', 'new-project': 'Proje Oluştur', 'project-detail': 'Proje Ayrıntısı', imports: 'Excel Aktarımı', users: 'Kullanıcı Yönetimi', notifications: 'Bildirimler', 'student-profile': 'Öğrenci Profili', years: 'Akademik Yıllar', account: 'Hesap Ayarları' }
  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? 'sidebar-open' : ''}`}>
      <div className="sidebar-brand"><div className="brand-mark">Ü</div><div><b>ÜNYE BİLSEM</b><small>PROJE TAKİP SİSTEMİ</small></div><button className="icon-button sidebar-close" onClick={() => setMobileNav(false)} aria-label="Menüyü kapat"><X size={18} /></button></div>
      <div className="side-caption">ÇALIŞMA ALANI</div>
      <nav className="side-nav">{visibleNav.map(({ id, label, icon: Icon }) => <button key={id} className={`nav-link ${screen === id || (id === 'students' && screen === 'student-profile') ? 'nav-active' : ''}`} onClick={() => { setScreen(id); setMobileNav(false) }}><Icon size={18} /><span>{label}</span>{id === 'notifications' && <span className="nav-dot" />}</button>)}</nav>
      <div className="sidebar-bottom"><div className="help-card"><div className="help-icon"><Sparkles size={18} /></div><b>Bir fikriniz mi var?</b><p>Öğrencilerinizin merakını projeye dönüştürün.</p><button onClick={() => setScreen('new-project')}>Yeni proje başlat <ChevronRight size={15} /></button></div><div className="user-card"><div className="avatar">{user.name.slice(0, 1).toLocaleUpperCase('tr-TR')}</div><div className="user-meta"><b>{user.name}</b><small>{user.role === 'ADMIN' ? 'Yönetici' : 'Öğretmen'}</small></div><button className="icon-button" title="Çıkış yap" onClick={() => void signOut()}><LogOut size={17} /></button></div></div>
    </aside>
    {mobileNav && <button className="nav-backdrop" onClick={() => setMobileNav(false)} aria-label="Menüyü kapat" />}
    <main className="main-area"><header className="topbar"><button className="icon-button mobile-menu" onClick={() => setMobileNav(true)} aria-label="Menüyü aç"><Menu size={20} /></button><div className="breadcrumb"><span>Ünye BİLSEM</span><ChevronRight size={14} /><b>{titles[screen]}</b></div><div className="topbar-actions"><span className="today-label">{new Intl.DateTimeFormat('tr-TR', { weekday: 'long', day: 'numeric', month: 'long' }).format(new Date())}</span><button className="icon-button notification-button" title="Bildirimler" onClick={() => setScreen('notifications')}><Bell size={18} /></button><div className="avatar avatar-small">{user.name.slice(0, 1).toLocaleUpperCase('tr-TR')}</div></div></header>
      <div className="page-content">{screen === 'dashboard' && <Dashboard user={user} refreshKey={refreshKey} go={setScreen} />}{screen === 'reports' && <Reports role={user.role} onOpenStudent={(id) => { setSelectedStudent(id); setScreen('student-profile') }} onOpenProject={(id) => { setSelectedProject(id); setScreen('project-detail') }} />}{screen === 'students' && <Students refreshKey={refreshKey} user={user} onOpen={(id) => { setSelectedStudent(id); setScreen('student-profile') }} />}{screen === 'student-profile' && selectedStudent && <StudentProfile studentId={selectedStudent} user={user} onBack={() => setScreen('students')} />}{screen === 'projects' && <Projects refreshKey={refreshKey} user={user} onOpen={(id) => { setSelectedProject(id); setScreen('project-detail') }} />}{screen === 'new-project' && <ProjectCreate onCreated={(id, warning) => { setSelectedProject(id); refresh(); setScreen('project-detail'); notify(warning ?? 'Proje oluşturuldu.', warning ? 'error' : 'success') }} />}{screen === 'project-detail' && selectedProject && <ProjectDetail projectId={selectedProject} user={user} onBack={() => setScreen('projects')} notify={notify} refresh={refresh} />}{screen === 'imports' && <ExcelImport notify={notify} refresh={refresh} />}{screen === 'users' && <UsersAdmin refreshKey={refreshKey} notify={notify} user={user} />}{screen === 'years' && <AcademicYears refreshKey={refreshKey} notify={notify} />}{screen === 'notifications' && <Notifications refreshKey={refreshKey} />}{screen === 'account' && <PasswordSettings onSaved={() => notify('Parolanız değiştirildi. Bu oturum açık kalır; diğer oturumlar kapatıldı.')} />}</div>
    </main>{toast && <div className={`toast toast-${toast.type}`} role="status">{toast.type === 'success' ? <Check size={17} /> : <Activity size={17} />}{toast.message}<button className="icon-button" onClick={() => setToast(null)} aria-label="Kapat"><X size={15} /></button></div>}
  </div>
}

function PasswordGate({ user, onChanged }: { user: UserProfile; onChanged: () => void }) {
  return <main className="password-gate"><section className="panel password-panel"><div className="submit-badge"><Shield size={20} /></div><div className="eyebrow">İLK GİRİŞ GÜVENLİĞİ</div><h1>Geçici parolanızı değiştirin</h1><p>{user.name}, devam etmeden önce hesabınıza özel yeni bir parola belirleyin.</p><PasswordForm onSaved={onChanged} /><button className="text-button password-signout" onClick={() => void signOut()}><LogOut size={15} /> Oturumu kapat</button></section></main>
}

function PasswordSettings({ onSaved }: { onSaved: () => void }) {
  return <><PageHeading eyebrow="HESAP" title="Şifre Değiştir" description="Hesabınızın parolasını güvenli biçimde güncelleyin." /><section className="panel password-panel"><PasswordForm onSaved={onSaved} /></section></>
}

function PasswordForm({ onSaved }: { onSaved: () => void }) {
  const [currentPassword, setCurrentPassword] = useState(''); const [newPassword, setNewPassword] = useState(''); const [confirmation, setConfirmation] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const [success, setSuccess] = useState('')
  async function submit(e: FormEvent) { e.preventDefault(); setError(''); setSuccess(''); if (newPassword.length < 8) { setError('Yeni parola en az 8 karakter olmalıdır.'); return }; if (newPassword !== confirmation) { setError('Yeni parolalar eşleşmiyor.'); return }; setBusy(true); try { const result = await apiRequest<{ message: string }>('/api/account/password', { method: 'POST', body: JSON.stringify({ currentPassword, newPassword, newPasswordConfirmation: confirmation }) }); setCurrentPassword(''); setNewPassword(''); setConfirmation(''); setSuccess(result.message); onSaved() } catch (error) { setError(error instanceof Error ? error.message : 'Parola değiştirilemedi. Mevcut parolanızı kontrol edin.') } finally { setBusy(false) } }
  return <form className="password-form" onSubmit={(e) => void submit(e)}><label className="field-label">Mevcut parola<input className="text-input" type="password" autoComplete="current-password" required value={currentPassword} onChange={(e) => setCurrentPassword(e.target.value)} /></label><label className="field-label">Yeni parola<input className="text-input" type="password" autoComplete="new-password" minLength={8} maxLength={128} required value={newPassword} onChange={(e) => setNewPassword(e.target.value)} /></label><label className="field-label">Yeni parola tekrarı<input className="text-input" type="password" autoComplete="new-password" minLength={8} maxLength={128} required value={confirmation} onChange={(e) => setConfirmation(e.target.value)} /></label>{error && <div className="form-error" role="alert">{error}</div>}{success && <div className="password-success" role="status">{success}</div>}<button className="button button-primary" disabled={busy}>{busy ? 'Güncelleniyor…' : 'Parolayı değiştir'}</button><small>En az 8 karakter. Başarılı değişiklikte diğer açık oturumlar kapatılır.</small></form>
}

function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) { return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{action}</div> }
function LoadingState() { return <div className="loading-state"><span className="spinner" />Bilgiler yükleniyor…</div> }
function ErrorState({ error, retry }: { error: unknown; retry: () => void }) { return <div className="error-state"><b>Bilgiler alınamadı</b><span>{error instanceof Error ? error.message : 'Sunucu hatası oluştu.'}</span><button className="button button-secondary" onClick={retry}>Yeniden dene</button></div> }
function EmptyState({ title, message, action }: { title: string; message: string; action?: ReactNode }) { return <div className="empty-state"><div className="empty-icon"><ClipboardList size={24} /></div><b>{title}</b><p>{message}</p>{action}</div> }
function Dashboard({ user, refreshKey, go }: { user: UserProfile; refreshKey: number; go: (screen: Screen) => void }) {
  const [summary, setSummary] = useState<DashboardSummary | null>(null); const [error, setError] = useState<unknown>(null)
  const load = useCallback(() => { setError(null); apiRequest<DashboardSummary>('/api/dashboard/summary').then(setSummary).catch(setError) }, [])
  useEffect(() => { const timer = window.setTimeout(() => load(), 0); return () => window.clearTimeout(timer) }, [load, refreshKey])
  if (error) return <><PageHeading eyebrow="ÇALIŞMA ALANI" title="Genel Bakış" description="Kurumunuzdaki güncel proje ve öğrenci görünümü." /><ErrorState error={error} retry={load} /></>
  if (!summary) return <><PageHeading eyebrow="ÇALIŞMA ALANI" title="Genel Bakış" description="Kurumunuzdaki güncel proje ve öğrenci görünümü." /><LoadingState /></>
  return <><PageHeading eyebrow="{ÜNYE BİLSEM} · ÇALIŞMA ALANI" title={`Merhaba, ${user.name.split(' ')[0]}`} description="Öğrencilerinizin fikirleri ve projeleri için güncel görünüm." action={<button className="button button-primary" onClick={() => go('new-project')}><Plus size={17} /> Yeni proje</button>} />
    <section className="welcome-banner"><div><div className="banner-kicker"><span className="status-pip" /> {summary.currentAcademicYear?.name ?? 'Akademik yıl tanımlanmamış'}</div><h2>Merak, keşif ve üretim<br />aynı yerde buluşuyor.</h2><p>Öğrenci çalışmalarını takip edin, yeni fikirleri projeye dönüştürün.</p></div><div className="banner-art"><div className="art-orbit" /><div className="art-core"><Sparkles size={32} /></div><span className="art-dot dot-a" /><span className="art-dot dot-b" /><span className="art-dot dot-c" /></div></section>
    <div className="stat-grid"><StatCard icon={<GraduationCap />} label="Aktif öğrenci" value={summary.activeStudentCount} tone="blue" hint="Güncel akademik yıl" /><StatCard icon={<FolderKanban />} label="Aktif proje" value={summary.activeProjectCount} tone="green" hint="Tüm çalışma yılları" /><StatCard icon={<Users />} label="Öğretmen" value={summary.activeTeacherCount} tone="violet" hint="Etkin kurum hesabı" /><StatCard icon={<Bell />} label="Okunmamış bildirim" value={summary.unreadNotificationCount} tone="amber" hint="Hesabınıza ait" /></div>
    <div className="dashboard-grid"><section className="panel"><div className="panel-heading"><div><h3>Son projeler</h3><p>Kurumda oluşturulan son çalışmalar</p></div><button className="text-button" onClick={() => go('projects')}>Tüm projeler <ChevronRight size={15} /></button></div>{summary.recentProjects.length ? <div className="recent-list">{summary.recentProjects.map((p) => <div className="recent-row" key={p.id}><div className="project-mark"><FolderKanban size={17} /></div><div className="recent-main"><b>{p.title}</b><span>{p.categoryName} · {p.academicYearName}</span></div><span className="badge badge-neutral">{p.statusName}</span></div>)}</div> : <EmptyState title="Henüz proje yok" message="İlk proje kaydınızı oluşturarak başlayabilirsiniz." action={<button className="button button-secondary" onClick={() => go('new-project')}><Plus size={15} /> Proje oluştur</button>} />}</section>
      <section className="panel category-panel"><div className="panel-heading"><div><h3>Proje alanları</h3><p>Kategori bazında aktif proje sayısı</p></div><BookOpen size={19} className="muted-icon" /></div>{summary.categoryDistribution.length ? <div className="category-list">{summary.categoryDistribution.map((c, i) => <div className="category-row" key={c.categoryId}><span className={`category-dot category-${i % 4}`} /><span>{c.categoryName}</span><b>{c.total}</b></div>)}</div> : <div className="mini-empty">Kategori dağılımı proje oluşturulduğunda görünür.</div>}</section></div>
    <div className="quick-actions"><button onClick={() => go('students')}><span className="quick-icon q-blue"><GraduationCap size={18} /></span><span><b>Öğrenci listesi</b><small>Öğrenci kayıtlarını görüntüle</small></span><ChevronRight size={17} /></button><button onClick={() => go(user.role === 'ADMIN' ? 'imports' : 'projects')}><span className="quick-icon q-green">{user.role === 'ADMIN' ? <FileSpreadsheet size={18} /> : <FolderKanban size={18} />}</span><span><b>{user.role === 'ADMIN' ? 'Excel aktarımı' : 'Proje çalışmaları'}</b><small>{user.role === 'ADMIN' ? 'Öğrenci listesini içe aktar' : 'Çalışmaları görüntüle'}</small></span><ChevronRight size={17} /></button><button onClick={() => go('notifications')}><span className="quick-icon q-amber"><Bell size={18} /></span><span><b>Bildirimler</b><small>Güncel bildirimlerinizi inceleyin</small></span><ChevronRight size={17} /></button></div>
  </>
}
function StatCard({ icon, label, value, tone, hint }: { icon: ReactNode; label: string; value: number; tone: string; hint: string }) { return <article className="stat-card"><div className={`stat-icon stat-${tone}`}>{icon}</div><span className="stat-label">{label}</span><strong>{value}</strong><small>{hint}</small></article> }

function Students({ refreshKey, onOpen, user }: { refreshKey: number; onOpen: (id: string) => void; user: UserProfile }) {
  const [search, setSearch] = useState('')
  const [term, setTerm] = useState('')
  const [talentArea, setTalentArea] = useState('')
  const [appliedTalentArea, setAppliedTalentArea] = useState('')
  const [advisorName, setAdvisorName] = useState('')
  const [appliedAdvisorName, setAppliedAdvisorName] = useState('')
  const [students, setStudents] = useState<Student[]>([])
  const [pagination, setPagination] = useState<ApiPage<Student>['pagination'] | null>(null)
  const [page, setPage] = useState(1)
  const [years, setYears] = useState<AcademicYear[]>([])
  const [yearId, setYearId] = useState('')
  const [error, setError] = useState<unknown>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    apiRequest<AcademicYear[]>('/api/academic-years')
      .then((items) => { setYears(items); const current = items.find((y) => y.isCurrent); if (current) setYearId(current.id) })
      .catch(() => {})
  }, [])

  const load = useCallback(() => {
    setLoading(true); setError(null)
    const query = new URLSearchParams({ page: String(page), pageSize: '20' })
    if (term) query.set('search', term)
    if (yearId) query.set('academicYearId', yearId)
    else query.set('allAcademicYears', 'true')
    if (appliedTalentArea) query.set('talentArea', appliedTalentArea)
    if (appliedAdvisorName) query.set('advisorName', appliedAdvisorName)
    fetch(`/api/students?${query}`, { credentials: 'include' })
      .then(async (response) => {
        const payload = await response.json()
        if (!response.ok || !payload.success) throw new ApiError(payload.error?.message ?? 'Öğrenciler yüklenemedi.', response.status)
        setStudents(payload.data as Student[])
        setPagination(payload.pagination as ApiPage<Student>['pagination'])
      })
      .catch(setError)
      .finally(() => setLoading(false))
  }, [page, term, yearId, appliedTalentArea, appliedAdvisorName])
  useEffect(() => { const timer = window.setTimeout(load, 0); return () => window.clearTimeout(timer) }, [load, refreshKey])

  function applyFilters(event: FormEvent) {
    event.preventDefault()
    setTerm(search.trim()); setAppliedTalentArea(talentArea.trim()); setAppliedAdvisorName(advisorName.trim()); setPage(1)
  }
  function clearFilters() {
    setSearch(''); setTerm(''); setTalentArea(''); setAppliedTalentArea(''); setAdvisorName(''); setAppliedAdvisorName(''); setYearId(years.find((year) => year.isCurrent)?.id ?? ''); setPage(1)
  }

  return <><PageHeading eyebrow="ÖĞRENCİ ÇALIŞMALARI" title="Öğrenciler" description="Ad veya BİLSEM numarasıyla arayın; akademik yıl, alan ve danışmana göre filtreleyin." action={<div className="heading-count"><b>{pagination?.total ?? 0}</b><span>kayıt</span></div>} />{user.role === 'ADMIN' && <StudentCreatePanel onSaved={() => { void load() }} />}
    <form className="panel filter-panel students-filter-panel" onSubmit={applyFilters}>
      <label className="student-filter-search"><span className="sr-only">Öğrenci ara</span><Search size={17} /><input type="search" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Ad soyad veya BİLSEM numarası" /></label>
      <label className="student-filter-field"><span>Akademik yıl</span><select aria-label="Akademik yıl" value={yearId} onChange={(event) => { setYearId(event.target.value); setPage(1) }}><option value="">Tüm akademik yıllar</option>{years.map((year) => <option key={year.id} value={year.id}>{year.name}</option>)}</select></label>
      <label className="student-filter-field"><span>Yetenek alanı</span><input value={talentArea} onChange={(event) => setTalentArea(event.target.value)} placeholder="Örn. Müzik" /></label>
      <label className="student-filter-field"><span>Danışman öğretmen</span><input value={advisorName} onChange={(event) => setAdvisorName(event.target.value)} placeholder="Öğretmen adı" /></label>
      <div className="student-filter-actions"><button className="button button-primary" type="submit">Filtrele</button><button className="button button-secondary" type="button" onClick={clearFilters}>Temizle</button></div>
    </form>
    {error ? <ErrorState error={error} retry={load} /> : loading ? <LoadingState /> : students.length ? <>
      <div className="panel table-panel students-desktop-list"><div className="table-wrap"><table><thead><tr><th>ÖĞRENCİ</th><th>BİLSEM NO</th><th>YETENEK ALANI</th><th>DANIŞMAN</th><th>OKUL / SINIF</th><th /></tr></thead><tbody>{students.map((student) => <tr key={student.enrollmentId} onClick={() => onOpen(student.studentId)} onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') onOpen(student.studentId) }} tabIndex={0} className="click-row"><td><div className="student-cell"><div className="student-avatar">{student.firstName.slice(0, 1)}{student.lastName.slice(0, 1)}</div><span><b>{personName(student.firstName, student.lastName)}</b><small>{student.className ? `${student.gradeLevel ?? ''}. sınıf · ${student.className}` : student.gradeLevel ? `${student.gradeLevel}. sınıf` : 'Öğrenci profili'}</small></span></div></td><td className="mono">{student.bilsemNo}</td><td><span className="badge badge-blue">{student.talentArea ?? '—'}</span></td><td>{student.advisorName ?? '—'}</td><td>{student.schoolName ?? '—'}</td><td><ChevronRight size={16} className="muted-icon" /></td></tr>)}</tbody></table></div></div>
      <div className="student-mobile-list">{students.map((student) => <button className="panel student-mobile-card" key={student.enrollmentId} onClick={() => onOpen(student.studentId)}><span className="student-avatar">{student.firstName.slice(0, 1)}{student.lastName.slice(0, 1)}</span><span className="student-mobile-main"><b>{personName(student.firstName, student.lastName)}</b><small className="mono">{student.bilsemNo}</small><span><strong>Yetenek alanı</strong>{student.talentArea ?? '—'}</span><span><strong>Danışman</strong>{student.advisorName ?? '—'}</span></span><ChevronRight size={17} className="muted-icon" /></button>)}</div>
      <Pagination page={page} pagination={pagination} setPage={setPage} />
    </> : <div className="panel"><EmptyState title="Öğrenci kaydı bulunamadı" message={term || appliedTalentArea || appliedAdvisorName ? 'Arama veya filtre ölçütlerinizi değiştirip yeniden deneyin.' : yearId ? 'Seçili akademik yıl için henüz öğrenci aktarılmamış.' : 'Henüz öğrenci kaydı bulunmuyor.'} action={(term || appliedTalentArea || appliedAdvisorName || yearId) ? <button className="button button-secondary" onClick={clearFilters}>Filtreleri temizle</button> : undefined} /></div>}
  </>
}
function StudentCreatePanel({ onSaved }: { onSaved: () => void }) {
  const [open, setOpen] = useState(false); const [years, setYears] = useState<AcademicYear[]>([]); const [teachers, setTeachers] = useState<Array<{ id: string; name: string }>>([]); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [form, setForm] = useState({ firstName: '', lastName: '', bilsemNo: '', academicYearId: '', talentArea: '', advisorUserId: '' });
  useEffect(() => { void Promise.all([apiRequest<AcademicYear[]>('/api/academic-years'), apiRequest<ProjectOptions>('/api/project-options').then((o) => o.teachers ?? [])]).then(([ys, ts]) => { setYears(ys); setTeachers(ts); setForm((f) => ({ ...f, academicYearId: ys.find((y) => y.isCurrent)?.id ?? ys[0]?.id ?? '' })) }).catch((e) => setError(e instanceof Error ? e.message : 'Form seçenekleri yüklenemedi.')) }, []);
  async function submit(e: FormEvent) { e.preventDefault(); setBusy(true); setError(''); try { await apiRequest('/api/admin/students', { method: 'POST', body: JSON.stringify({ ...form, advisorUserId: form.advisorUserId || null }) }); setForm({ firstName: '', lastName: '', bilsemNo: '', academicYearId: years.find((y) => y.isCurrent)?.id ?? '', talentArea: '', advisorUserId: '' }); setOpen(false); onSaved() } catch (e) { setError(e instanceof Error ? e.message : 'Öğrenci oluşturulamadı.') } finally { setBusy(false) } }
  return <section className="panel student-admin-panel"><div className="panel-heading"><div><h3>Manuel öğrenci kaydı</h3><p>Ana öğrenci bilgileri ile ilk akademik yıl kaydını birlikte ekleyin.</p></div><button className="button button-secondary" onClick={() => setOpen((v) => !v)}>{open ? 'Kapat' : 'Öğrenci ekle'}</button></div>{open && <form className="student-admin-form" onSubmit={(e) => void submit(e)}><div className="student-admin-section"><b>Öğrenci ana bilgileri</b><div className="form-two-col"><label className="field-label">Ad<input className="text-input" required value={form.firstName} onChange={(e) => setForm({ ...form, firstName: e.target.value })} /></label><label className="field-label">Soyad<input className="text-input" required value={form.lastName} onChange={(e) => setForm({ ...form, lastName: e.target.value })} /></label><label className="field-label">BİLSEM numarası<input className="text-input" required inputMode="numeric" pattern="[0-9]+" value={form.bilsemNo} onChange={(e) => setForm({ ...form, bilsemNo: e.target.value })} /></label></div></div><div className="student-admin-section"><b>Akademik yıl kaydı</b><div className="form-two-col"><label className="field-label">Akademik yıl<select className="text-input" required value={form.academicYearId} onChange={(e) => setForm({ ...form, academicYearId: e.target.value })}><option value="">Seçin</option>{years.map((y) => <option key={y.id} value={y.id}>{y.name}</option>)}</select></label><label className="field-label">Yetenek alanı<input className="text-input" required value={form.talentArea} onChange={(e) => setForm({ ...form, talentArea: e.target.value })} /></label><label className="field-label">Danışman öğretmen<select className="text-input" value={form.advisorUserId} onChange={(e) => setForm({ ...form, advisorUserId: e.target.value })}><option value="">Atanmamış</option>{teachers.map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}</select></label></div></div>{error && <div className="form-error" role="alert">{error}</div>}<button className="button button-primary" disabled={busy}>{busy ? 'Kaydediliyor…' : 'Öğrenciyi kaydet'}</button></form>}</section>
}
function Pagination({ page, pagination, setPage }: { page: number; pagination: ApiPage<unknown>['pagination'] | null; setPage: (p: number) => void }) { if (!pagination || pagination.totalPages <= 1) return null; return <div className="pagination"><span>{pagination.total} kaydın {((page - 1) * pagination.pageSize) + 1}–{Math.min(page * pagination.pageSize, pagination.total)} arası</span><div><button className="icon-button" disabled={page <= 1} onClick={() => setPage(page - 1)} aria-label="Önceki sayfa"><ChevronLeft size={18} /></button><b>{page} / {pagination.totalPages}</b><button className="icon-button" disabled={page >= pagination.totalPages} onClick={() => setPage(page + 1)} aria-label="Sonraki sayfa"><ChevronRight size={18} /></button></div></div> }
function StudentProfile({ studentId, onBack, user }: { studentId: string; onBack: () => void; user: UserProfile }) {
  const [profile, setProfile] = useState<StudentProfileData | null>(null)
  const [history, setHistory] = useState<StudentProject[]>([])
  const [error, setError] = useState<unknown>(null)
  const [loading, setLoading] = useState(true)
  const load = useCallback(() => {
    setLoading(true); setError(null)
    Promise.all([apiRequest<StudentProfileData>(`/api/students/${studentId}`), apiRequest<StudentProject[]>(`/api/students/${studentId}/history`)])
      .then(([studentProfile, projects]) => { setProfile(studentProfile); setHistory(projects) })
      .catch(setError)
      .finally(() => setLoading(false))
  }, [studentId])
  useEffect(() => { const timer = window.setTimeout(load, 0); return () => window.clearTimeout(timer) }, [load])

  if (error) return <><button className="back-link" onClick={onBack}><ChevronLeft size={16} /> Öğrenci listesine dön</button><ErrorState error={error} retry={load} /></>
  if (loading || !profile) return <><button className="back-link" onClick={onBack}><ChevronLeft size={16} /> Öğrenci listesine dön</button><LoadingState /></>

  const student = profile.student
  const current = profile.enrollments.find((enrollment) => enrollment.isCurrentAcademicYear) ?? profile.enrollments.find((enrollment) => enrollment.isActive) ?? profile.enrollments[0]
  const projectsByYear = history.reduce<Record<string, StudentProject[]>>((groups, project) => {
    groups[project.academicYear] = [...(groups[project.academicYear] ?? []), project]
    return groups
  }, {})

  return <>
    <button className="back-link" onClick={onBack}><ChevronLeft size={16} /> Öğrenci listesine dön</button>
    <section className="profile-hero"><div className="profile-avatar">{student.firstName.slice(0, 1)}{student.lastName.slice(0, 1)}</div><div><div className="eyebrow">ÖĞRENCİ PROFİLİ</div><h1>{personName(student.firstName, student.lastName)}</h1><p>BİLSEM No: <b>{student.bilsemNo}</b></p></div></section>
    {user.role === 'ADMIN' && <StudentProfileAdmin profile={profile} onSaved={() => { void load() }} />}
    <section className="student-summary-grid" aria-label="Güncel öğrenci bilgileri">
      <article className="panel student-summary-item"><small>GÜNCEL AKADEMİK YIL</small><b>{current?.academicYearName ?? 'Güncel yıl kaydı yok'}</b></article>
      <article className="panel student-summary-item"><small>YETENEK ALANI</small><b>{current?.talentArea ?? '—'}</b></article>
      <article className="panel student-summary-item"><small>DANIŞMAN ÖĞRETMEN</small><b>{current?.advisorName ?? '—'}</b></article>
      <article className="panel student-summary-item"><small>SİSTEME KAYIT</small><b>{dateLabel(student.createdAt)}</b></article>
    </section>
    <section className="panel profile-years-panel"><div className="panel-heading"><div><h3>Akademik yıl kayıtları</h3><p>Yıllara göre okul ve danışman bilgileri</p></div></div>{profile.enrollments.length ? <div className="enrollment-list">{profile.enrollments.map((enrollment) => <article key={enrollment.enrollmentId} className="enrollment-card"><div className="enrollment-year"><CalendarDays size={17} /><b>{enrollment.academicYearName}</b>{enrollment.isCurrentAcademicYear && <span className="badge badge-green">Güncel</span>}</div><span><small>YETENEK ALANI</small>{enrollment.talentArea ?? '—'}</span><span><small>DANIŞMAN</small>{enrollment.advisorName ?? '—'}</span><span><small>OKUL / SINIF</small>{enrollment.schoolName ?? '—'}{enrollment.gradeLevel ? ` · ${enrollment.gradeLevel}. sınıf ${enrollment.className ?? ''}` : ''}</span></article>)}</div> : <EmptyState title="Akademik kayıt yok" message="Bu öğrenci için henüz akademik yıl kaydı bulunmuyor." />}</section>
    <section className="panel profile-projects-panel"><div className="panel-heading"><div><h3>Proje geçmişi</h3><p>Tüm akademik yıllardaki bireysel ve takım projeleri</p></div><span className="heading-count"><b>{history.length}</b><span>proje</span></span></div>{history.length ? <div className="project-history-years">{Object.entries(projectsByYear).map(([academicYear, projects]) => <section className="project-history-year" key={academicYear}><div className="project-history-year-title"><CalendarDays size={16} /><h4>{academicYear}</h4><span>{projects.length} proje</span></div><div className="project-history-list">{projects.map((project) => <article className="project-history-card" key={project.projectId}><div className="project-mark"><FolderKanban size={17} /></div><div className="project-history-main"><div className="project-history-label">{project.category}</div><h4>{project.title}</h4><div className="project-history-meta"><span><small>DURUM</small><b>{project.status}</b></span><span><small>KATILIM</small><b>{project.participationType === 'TEAM' ? `Takım${project.teamName ? ` · ${project.teamName}` : ''}` : 'Bireysel'}</b></span><span><small>DANIŞMAN</small><b>{project.advisors.length ? project.advisors.map((advisor) => advisor.name).join(', ') : 'Atanmamış'}</b></span></div></div></article>)}</div></section>)}</div> : <EmptyState title="Proje geçmişi bulunmuyor" message="Öğrencinin tüm yıllardaki projeleri burada listelenir. Takım projeleri her katılımcının profilinde görünür." />}</section>
  </>
}

function StudentProfileAdmin({ profile, onSaved }: { profile: StudentProfileData; onSaved: () => void }) {
  const [years, setYears] = useState<AcademicYear[]>([]); const [teachers, setTeachers] = useState<Array<{ id: string; name: string }>>([]); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [basic, setBasic] = useState({ bilsemNo: profile.student.bilsemNo, firstName: profile.student.firstName, lastName: profile.student.lastName }); const [enrollment, setEnrollment] = useState({ academicYearId: '', talentArea: '', advisorUserId: '' });
  useEffect(() => { void Promise.all([apiRequest<AcademicYear[]>('/api/academic-years'), apiRequest<ProjectOptions>('/api/project-options')]).then(([ys, options]) => { setYears(ys); setTeachers(options.teachers ?? []); setEnrollment((v) => ({ ...v, academicYearId: ys.find((y) => y.isCurrent && !profile.enrollments.some((e) => e.academicYearId === y.id))?.id ?? ys.find((y) => !profile.enrollments.some((e) => e.academicYearId === y.id))?.id ?? '' })) }).catch((e) => setError(e instanceof Error ? e.message : 'Seçenekler alınamadı.')) }, [profile.enrollments]);
  async function updateBasic(e: FormEvent) { e.preventDefault(); setBusy(true); setError(''); try { await apiRequest(`/api/admin/students/${profile.student.id}`, { method: 'PATCH', body: JSON.stringify(basic) }); onSaved() } catch (e) { setError(e instanceof Error ? e.message : 'Öğrenci bilgileri kaydedilemedi.') } finally { setBusy(false) } }
  async function addEnrollment(e: FormEvent) { e.preventDefault(); setBusy(true); setError(''); try { await apiRequest(`/api/admin/students/${profile.student.id}/enrollments`, { method: 'POST', body: JSON.stringify({ ...enrollment, advisorUserId: enrollment.advisorUserId || null }) }); onSaved() } catch (e) { setError(e instanceof Error ? e.message : 'Akademik yıl kaydı eklenemedi.') } finally { setBusy(false) } }
  return <section className="panel student-admin-panel"><div className="panel-heading"><div><h3>Yönetici öğrenci işlemleri</h3><p>Ana bilgiler ve akademik yıl kayıtları ayrı yönetilir; geçmiş yıl kayıtları korunur.</p></div></div><div className="student-admin-grid"><form className="student-admin-form" onSubmit={(e) => void updateBasic(e)}><b>Öğrenci ana bilgileri</b><label className="field-label">Ad<input className="text-input" required value={basic.firstName} onChange={(e) => setBasic({ ...basic, firstName: e.target.value })} /></label><label className="field-label">Soyad<input className="text-input" required value={basic.lastName} onChange={(e) => setBasic({ ...basic, lastName: e.target.value })} /></label><label className="field-label">BİLSEM numarası<input className="text-input" required inputMode="numeric" pattern="[0-9]+" value={basic.bilsemNo} onChange={(e) => setBasic({ ...basic, bilsemNo: e.target.value })} /></label><button className="button button-secondary" disabled={busy}>Ana bilgileri kaydet</button></form><form className="student-admin-form" onSubmit={(e) => void addEnrollment(e)}><b>Yeni akademik yıl kaydı</b><label className="field-label">Akademik yıl<select className="text-input" required value={enrollment.academicYearId} onChange={(e) => setEnrollment({ ...enrollment, academicYearId: e.target.value })}><option value="">Seçin</option>{years.filter((y) => !profile.enrollments.some((en) => en.academicYearId === y.id)).map((y) => <option key={y.id} value={y.id}>{y.name}</option>)}</select></label><label className="field-label">Yetenek alanı<input className="text-input" required value={enrollment.talentArea} onChange={(e) => setEnrollment({ ...enrollment, talentArea: e.target.value })} /></label><label className="field-label">Danışman öğretmen<select className="text-input" value={enrollment.advisorUserId} onChange={(e) => setEnrollment({ ...enrollment, advisorUserId: e.target.value })}><option value="">Atanmamış</option>{teachers.map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}</select></label><button className="button button-primary" disabled={busy || !enrollment.academicYearId}>Yıl kaydı ekle</button></form></div>{profile.enrollments.map((record) => <EditStudentEnrollment key={record.enrollmentId} studentId={profile.student.id} enrollment={record} teachers={teachers} onSaved={onSaved} />)}{error && <div className="form-error" role="alert">{error}</div>}</section>
}

function EditStudentEnrollment({ studentId, enrollment, teachers, onSaved }: { studentId: string; enrollment: StudentProfileData['enrollments'][number]; teachers: Array<{ id: string; name: string }>; onSaved: () => void }) {
  const [talentArea, setTalentArea] = useState(enrollment.talentArea ?? ''); const [advisorUserId, setAdvisorUserId] = useState(enrollment.advisorUserId ?? ''); const [busy, setBusy] = useState(false); const [error, setError] = useState('')
  async function submit(e: FormEvent) { e.preventDefault(); setBusy(true); setError(''); try { await apiRequest(`/api/admin/students/${studentId}/enrollments/${enrollment.enrollmentId}`, { method: 'PATCH', body: JSON.stringify({ talentArea, advisorUserId: advisorUserId || null }) }); onSaved() } catch (e) { setError(e instanceof Error ? e.message : 'Yıl kaydı güncellenemedi.') } finally { setBusy(false) } }
  return <form className="student-admin-form student-enrollment-edit" onSubmit={(e) => void submit(e)}><b>{enrollment.academicYearName} kaydını düzenle</b><label className="field-label">Yetenek alanı<input className="text-input" required value={talentArea} onChange={(e) => setTalentArea(e.target.value)} /></label><label className="field-label">Danışman öğretmen<select className="text-input" value={advisorUserId} onChange={(e) => setAdvisorUserId(e.target.value)}><option value="">Atanmamış</option>{teachers.map((teacher) => <option key={teacher.id} value={teacher.id}>{teacher.name}</option>)}</select></label>{error && <div className="form-error" role="alert">{error}</div>}<button className="button button-secondary" disabled={busy}>Bu yıl kaydını güncelle</button></form>
}

function Projects({ refreshKey, user, onOpen }: { refreshKey: number; user: UserProfile; onOpen: (id: string) => void }) {
  const [items, setItems] = useState<Project[]>([]); const [years, setYears] = useState<AcademicYear[]>([]); const [options, setOptions] = useState<ProjectOptions | null>(null); const [students, setStudents] = useState<Student[]>([]); const [pagination, setPagination] = useState({ page: 1, pageSize: 20, total: 0, totalPages: 0 }); const [search, setSearch] = useState(''); const [filters, setFilters] = useState({ academicYearId: '', categoryId: '', statusId: '', studentId: '', advisorUserId: '', includeArchived: false }); const [error, setError] = useState<unknown>(null); const [loading, setLoading] = useState(true);
  useEffect(() => { void Promise.all([apiRequest<AcademicYear[]>('/api/academic-years'), apiRequest<ProjectOptions>('/api/project-options'), apiRequest<Student[]>('/api/students?page=1&pageSize=100')]).then(([y, o, s]) => { setYears(y); setOptions(o); setStudents(s) }).catch(setError) }, [user.role]);
  const load = useCallback(() => { setLoading(true); setError(null); const q = new URLSearchParams({ page: String(pagination.page), pageSize: String(pagination.pageSize) }); if (search.trim()) q.set('search', search.trim()); for (const [key, value] of Object.entries(filters)) if (value) q.set(key, String(value)); fetch('/api/projects?' + q, { credentials: 'include' }).then(async (r) => { const body = await r.json(); if (!r.ok || !body.success) throw new Error(body.error?.message ?? 'Projeler alınamadı.'); setItems(body.data); setPagination((p) => ({ ...p, ...body.pagination })) }).catch(setError).finally(() => setLoading(false)) }, [filters, pagination.page, pagination.pageSize, search]);
  useEffect(() => { const timer = window.setTimeout(() => void load(), 250); return () => window.clearTimeout(timer) }, [load, refreshKey]);
  const change = (key: keyof typeof filters, value: string | boolean) => { setFilters((f) => ({ ...f, [key]: value })); setPagination((p) => ({ ...p, page: 1 })) };
  return <><PageHeading eyebrow="PROJE ÇALIŞMALARI" title="Projeler" description="Projeleri arayın, filtreleyin ve durumlarını takip edin." action={<span className="heading-count"><b>{pagination.total}</b><span>proje</span></span>} /><section className="panel students-filter-panel project-filters"><label className="student-filter-search"><Search size={16} /><input aria-label="Proje adıyla ara" placeholder="Proje adına göre ara" value={search} onChange={(e) => { setSearch(e.target.value); setPagination((p) => ({ ...p, page: 1 })) }} /></label><label className="student-filter-field"><span>Akademik yıl</span><select value={filters.academicYearId} onChange={(e) => change('academicYearId', e.target.value)}><option value="">Tüm yıllar</option>{years.map((y) => <option key={y.id} value={y.id}>{y.name}</option>)}</select></label><label className="student-filter-field"><span>Kategori</span><select value={filters.categoryId} onChange={(e) => change('categoryId', e.target.value)}><option value="">Tüm kategoriler</option>{options?.categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="student-filter-field"><span>Durum</span><select value={filters.statusId} onChange={(e) => change('statusId', e.target.value)}><option value="">Tüm durumlar</option>{options?.statuses.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label className="student-filter-field"><span>Öğrenci</span><select value={filters.studentId} onChange={(e) => change('studentId', e.target.value)}><option value="">Tüm öğrenciler</option>{students.map((s) => <option key={s.studentId} value={s.studentId}>{personName(s.firstName, s.lastName)}</option>)}</select></label><label className="student-filter-field"><span>Danışman</span><select value={filters.advisorUserId} onChange={(e) => change('advisorUserId', e.target.value)}><option value="">Tüm danışmanlar</option>{options?.teachers?.map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}</select></label>{user.role === 'ADMIN' && <label className="project-archive-toggle"><input type="checkbox" checked={filters.includeArchived} onChange={(e) => change('includeArchived', e.target.checked)} /> Arşivlenmişleri göster</label>}</section>{error ? <ErrorState error={error} retry={load} /> : loading ? <LoadingState /> : items.length ? <><div className="project-grid">{items.map((p) => <button className="project-card project-card-button" key={p.id} onClick={() => onOpen(p.id)}><div className="project-card-top"><div className="project-mark"><FolderKanban size={19} /></div><span className="badge badge-neutral">{p.statusName}</span></div><div className="eyebrow">{p.categoryName} · {p.academicYearName}</div><h3>{p.title}</h3><p>{p.description || 'Bu proje için açıklama eklenmemiş.'}</p><div className="project-card-people"><span><b>Öğrenciler:</b> {p.students?.join(', ') || 'Öğrenci bilgisi yok'}</span><span><b>Danışmanlar:</b> {p.advisors?.join(', ') || 'Atanmamış'}</span></div><div className="project-card-foot"><span>{p.participationType === 'TEAM' ? `Takım · ${p.teamName || 'Adsız'}` : 'Bireysel'} · {p.creatorName}</span><span>{dateLabel(p.createdAt)}</span></div><span className="project-card-open">Ayrıntıları görüntüle <ChevronRight size={14} /></span></button>)}</div><div className="project-pagination"><span>{pagination.total} projeden {items.length} kayıt gösteriliyor</span><button className="button button-secondary" disabled={pagination.page <= 1} onClick={() => setPagination((p) => ({ ...p, page: p.page - 1 }))}>Önceki</button><b>{pagination.page} / {Math.max(1, pagination.totalPages)}</b><button className="button button-secondary" disabled={pagination.page >= pagination.totalPages} onClick={() => setPagination((p) => ({ ...p, page: p.page + 1 }))}>Sonraki</button></div></> : <div className="panel"><EmptyState title="Eşleşen proje bulunamadı" message="Filtreleri temizleyebilir veya farklı bir arama yapabilirsiniz." /></div>}</>
}
type ProjectDetailData = { project: Project & { deletedAt: string | null }; students: Array<{ enrollmentId: string; studentId: string; bilsemNo: string; firstName: string; lastName: string; gradeLevel: number | null; className: string | null }>; advisors: Array<{ userId: string; name: string; email: string; isPrimary: boolean }> }
function ProjectDetail({ projectId, user, onBack, notify, refresh }: { projectId: string; user: UserProfile; onBack: () => void; notify: (message: string, type?: Toast['type']) => void; refresh: () => void }) {
  const [detail, setDetail] = useState<ProjectDetailData | null>(null); const [options, setOptions] = useState<ProjectOptions | null>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState<unknown>(null); const [editing, setEditing] = useState(false); const [form, setForm] = useState({ title: '', description: '', statusId: '', teamName: '' });
  const load = useCallback(() => { setError(null); void Promise.all([apiRequest<ProjectDetailData>(`/api/projects/${projectId}`), apiRequest<ProjectOptions>('/api/project-options')]).then(([d, o]) => { setDetail(d); setOptions(o); setForm({ title: d.project.title, description: d.project.description ?? '', statusId: d.project.statusId, teamName: d.project.teamName ?? '' }) }).catch(setError) }, [projectId]); useEffect(() => { const timer = window.setTimeout(() => void load(), 0); return () => window.clearTimeout(timer) }, [load]);
  if (error) return <><button className="text-button" onClick={onBack}><ChevronLeft size={15} /> Projelere dön</button><ErrorState error={error} retry={load} /></>; if (!detail) return <LoadingState />;
  const p = detail.project; const canEdit = !p.deletedAt && (user.role === 'ADMIN' || p.createdBy === user.id); const canArchive = !p.deletedAt && (user.role === 'ADMIN' || p.createdBy === user.id);
  async function save(e: FormEvent) { e.preventDefault(); setBusy(true); try { await apiRequest(`/api/projects/${projectId}`, { method: 'PATCH', body: JSON.stringify({ title: form.title.trim(), description: form.description.trim() || null, statusId: form.statusId, teamName: p.participationType === 'TEAM' ? form.teamName.trim() || null : null }) }); notify('Proje güncellendi.'); setEditing(false); refresh(); await load() } catch (err) { notify(err instanceof Error ? err.message : 'Proje güncellenemedi.', 'error') } finally { setBusy(false) } }
  async function archive() { setBusy(true); try { await apiRequest(`/api/projects/${projectId}/archive`, { method: 'POST' }); notify('Proje arşivlendi.'); refresh(); await load() } catch (err) { notify(err instanceof Error ? err.message : 'Proje arşivlenemedi.', 'error') } finally { setBusy(false) } }
  async function restore() { setBusy(true); try { await apiRequest(`/api/projects/${projectId}/restore`, { method: 'POST' }); notify('Proje geri yüklendi.'); refresh(); await load() } catch (err) { notify(err instanceof Error ? err.message : 'Proje geri yüklenemedi.', 'error') } finally { setBusy(false) } }
  return <><button className="text-button project-back" onClick={onBack}><ChevronLeft size={15} /> Projelere dön</button><PageHeading eyebrow="PROJE AYRINTISI" title={p.title} description={`${p.categoryName} · ${p.academicYearName}`} action={<span className="badge badge-neutral">{p.statusName}</span>} />{p.deletedAt && <div className="info-note project-archived-note"><b>Bu proje arşivlenmiş.</b><p>Normal proje listesinde görünmez ve düzenlemeye kapalıdır.</p></div>}<div className="project-detail-layout"><section className="panel project-detail-main"><div className="panel-heading"><div><h3>Proje bilgileri</h3><p>{p.participationType === 'TEAM' ? `Takım projesi${p.teamName ? ` · ${p.teamName}` : ''}` : 'Bireysel proje'}</p></div>{canEdit && <button className="button button-secondary" onClick={() => setEditing(!editing)}>{editing ? 'Düzenlemeyi kapat' : 'Düzenle'}</button>}</div>{editing && canEdit ? <form className="project-edit-form" onSubmit={(e) => void save(e)}><label className="field-label">Proje adı<input className="text-input" maxLength={200} required value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} /></label><label className="field-label">Açıklama<textarea className="text-input" rows={4} value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} /></label><div className="form-two-col"><label className="field-label">Durum<select className="text-input" value={form.statusId} onChange={(e) => setForm({ ...form, statusId: e.target.value })}>{options?.statuses.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></label>{p.participationType === 'TEAM' && <label className="field-label">Takım adı<input className="text-input" value={form.teamName} onChange={(e) => setForm({ ...form, teamName: e.target.value })} /></label>}</div><button className="button button-primary" disabled={busy}>Değişiklikleri kaydet</button></form> : <div className="project-info-grid"><div><small>AÇIKLAMA</small><p>{p.description || 'Açıklama eklenmemiş.'}</p></div><div><small>AKADEMİK YIL</small><b>{p.academicYearName}</b></div><div><small>KATEGORİ</small><b>{p.categoryName}</b></div><div><small>DURUM</small><b>{p.statusName}</b></div><div><small>KATILIM</small><b>{p.participationType === 'TEAM' ? `Takım${p.teamName ? ` · ${p.teamName}` : ''}` : 'Bireysel'}</b></div><div><small>OLUŞTURAN ÖĞRETMEN</small><b>{p.creatorName}</b></div><div><small>DANIŞMAN ÖĞRETMENLER</small><b>{detail.advisors.length ? detail.advisors.map((a) => a.name).join(', ') : 'Danışman atanmamış'}</b></div></div>}<div className="project-members"><h3>İlgili öğrenciler <span>{detail.students.length}</span></h3>{detail.students.map((s) => <div className="project-member" key={s.enrollmentId}><span className="student-avatar">{s.firstName.slice(0, 1)}{s.lastName.slice(0, 1)}</span><b>{personName(s.firstName, s.lastName)}</b><small>{s.bilsemNo}{s.className ? ` · ${s.className}` : ''}</small></div>)}</div></section><aside className="panel project-actions"><h3>Proje işlemleri</h3><p>{p.createdBy === user.id ? 'Bu projeyi siz oluşturdunuz.' : 'Oluşturan öğretmen: ' + p.creatorName}</p>{canArchive && <button className="button button-secondary" disabled={busy} onClick={() => void archive()}>Projeyi arşivle</button>}{p.deletedAt && user.role === 'ADMIN' && <button className="button button-primary" disabled={busy} onClick={() => void restore()}>Arşivden geri yükle</button>}{!canEdit && !p.deletedAt && <small>Düzenleme yalnızca projeyi oluşturan öğretmen ve yöneticiler tarafından yapılabilir.</small>}</aside></div></>
}

function ProjectCreate({ onCreated }: { onCreated: (projectId: string, warning?: string) => void }) { const [years, setYears] = useState<AcademicYear[]>([]); const [options, setOptions] = useState<ProjectOptions | null>(null); const [students, setStudents] = useState<Student[]>([]); const [studentsTotal, setStudentsTotal] = useState(0); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [search, setSearch] = useState(''); const [selected, setSelected] = useState<string[]>([]); const [error, setError] = useState(''); const [form, setForm] = useState({ title: '', description: '', academicYearId: '', categoryId: '', statusId: '', participationType: 'INDIVIDUAL' as 'INDIVIDUAL' | 'TEAM', teamName: '' });
  useEffect(() => { Promise.all([apiRequest<AcademicYear[]>('/api/academic-years'), apiRequest<ProjectOptions>('/api/project-options')]).then(([y, o]) => { setYears(y); setOptions(o); const active = y.find((a) => a.isCurrent) ?? y[0]; setForm((f) => ({ ...f, academicYearId: active?.id ?? '', categoryId: o.categories[0]?.id ?? '', statusId: o.statuses[0]?.id ?? '' })) }).catch((e) => setError(e instanceof Error ? e.message : 'Form bilgileri alınamadı.')).finally(() => setLoading(false)) }, [])
  useEffect(() => { const q = new URLSearchParams({ page: '1', pageSize: '100' }); if (form.academicYearId) q.set('academicYearId', form.academicYearId); if (search.trim()) q.set('search', search.trim()); fetch('/api/students?' + q, { credentials: 'include' }).then(async (r) => { const j = await r.json(); if (r.ok && j.success) { setStudents(j.data); setStudentsTotal(j.pagination.total) } }).catch(() => {}) }, [form.academicYearId, search])
  const schema = z.object({ title: z.string().trim().min(1, 'Proje başlığı zorunludur.').max(200), description: z.string().max(10000), academicYearId: z.string().min(1, 'Akademik yıl seçin.'), categoryId: z.string().min(1, 'Proje kategorisi seçin.'), statusId: z.string().min(1, 'Proje durumu seçin.'), participationType: z.enum(['INDIVIDUAL', 'TEAM']), teamName: z.string(), enrollmentIds: z.array(z.string()).min(1, 'En az bir öğrenci seçin.') })
  async function submit(event: FormEvent) { event.preventDefault(); setError(''); const parsed = schema.safeParse({ ...form, enrollmentIds: selected }); if (!parsed.success) { setError(parsed.error.issues[0]?.message ?? 'Form bilgilerini kontrol edin.'); return }; if (form.participationType === 'INDIVIDUAL' && selected.length !== 1) { setError('Bireysel projede yalnızca bir öğrenci seçin.'); return }; if (form.participationType === 'TEAM' && selected.length < 2) { setError('Takım projesi için en az iki öğrenci seçin.'); return }; if (form.participationType === 'TEAM' && !form.teamName.trim()) { setError('Takım çalışması için takım adı girin.'); return } setBusy(true); try { const result = await apiRequest<{ projectId: string; conflicts: Array<{ enrollmentId: string; message: string }> }>('/api/projects', { method: 'POST', body: JSON.stringify({ ...form, title: form.title.trim(), description: form.description.trim() || null, teamName: form.participationType === 'TEAM' ? form.teamName.trim() : null, enrollmentIds: selected }) }); onCreated(result.projectId, result.conflicts.length ? `${result.conflicts.length} öğrenci için mükerrerlik uyarısı var.` : undefined) } catch (e) { setError(e instanceof Error ? e.message : 'Proje kaydedilemedi.') } finally { setBusy(false) } }
  if (loading) return <><PageHeading eyebrow="PROJE ÇALIŞMALARI" title="Proje Oluştur" description="Öğrenci çalışması için yeni proje kaydı hazırlayın." /><LoadingState /></>
  return <><PageHeading eyebrow="PROJE ÇALIŞMALARI" title="Proje Oluştur" description="Öğrenci çalışması için yeni proje kaydı hazırlayın." /><form className="create-project-layout" onSubmit={submit}><div className="form-column"><section className="panel form-panel"><div className="form-section-title"><span>01</span><div><h3>Proje bilgileri</h3><p>Çalışmanın temel bilgilerini girin.</p></div></div><label className="field-label">Proje başlığı <span className="required">*</span><input className="text-input" maxLength={200} value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} placeholder="Örn. Doğal yaşamı gözlemliyoruz" /></label><label className="field-label">Proje açıklaması<textarea className="text-input" rows={4} maxLength={10000} value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="Projenin amacı ve kısa içeriği" /></label><div className="form-two-col"><label className="field-label">Akademik yıl <span className="required">*</span><select className="text-input" value={form.academicYearId} onChange={(e) => setForm({ ...form, academicYearId: e.target.value })}><option value="">Seçin</option>{years.map((y) => <option key={y.id} value={y.id}>{y.name}{y.isCurrent ? ' · Güncel' : ''}</option>)}</select></label><label className="field-label">Proje kategorisi <span className="required">*</span><select className="text-input" value={form.categoryId} onChange={(e) => setForm({ ...form, categoryId: e.target.value })}><option value="">Seçin</option>{options?.categories.map((c) => <option value={c.id} key={c.id}>{c.name}</option>)}</select></label></div><div className="form-two-col"><label className="field-label">Proje durumu<select className="text-input" value={form.statusId} onChange={(e) => setForm({ ...form, statusId: e.target.value })}>{options?.statuses.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label className="field-label">Katılım türü<select className="text-input" value={form.participationType} onChange={(e) => setForm({ ...form, participationType: e.target.value as 'INDIVIDUAL' | 'TEAM' })}><option value="INDIVIDUAL">Bireysel</option><option value="TEAM">Takım</option></select></label></div>{form.participationType === 'TEAM' && <label className="field-label">Takım adı <span className="required">*</span><input className="text-input" value={form.teamName} onChange={(e) => setForm({ ...form, teamName: e.target.value })} placeholder="Takım adı" /></label>}</section><section className="panel form-panel"><div className="form-section-title"><span>02</span><div><h3>Öğrencileri seçin</h3><p>Projeye en az bir öğrenci ekleyin. {selected.length} öğrenci seçildi.</p></div></div><div className="search-wrap student-picker-search"><Search size={16} /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Öğrenci ara" /></div>{students.length ? <div className="student-picker">{students.map((s) => <label className="student-option" key={s.enrollmentId}><input type="checkbox" checked={selected.includes(s.enrollmentId)} onChange={(e) => setSelected(e.target.checked ? [...selected, s.enrollmentId] : selected.filter((id) => id !== s.enrollmentId))} /><span className="student-avatar">{s.firstName.slice(0, 1)}{s.lastName.slice(0, 1)}</span><span><b>{personName(s.firstName, s.lastName)}</b><small>{s.bilsemNo} · {s.talentArea ?? 'Yetenek alanı yok'}</small></span><span className="check-box"><Check size={14} /></span></label>)}</div> : <div className="mini-empty">{studentsTotal ? 'Bu aramayla eşleşen öğrenci bulunamadı.' : 'Seçilen akademik yılda öğrenci kaydı yok. Önce Excel aktarımıyla öğrenci ekleyin.'}</div>}</section></div><aside className="form-aside"><div className="panel submit-panel"><div className="submit-badge"><Sparkles size={20} /></div><h3>Projeyi kaydetmeye hazır mısınız?</h3><p>Proje ve öğrenci ilişkileri seçtiğiniz akademik yıl altında kaydedilir.</p>{error && <div className="form-error" role="alert">{error}</div>}<button className="button button-primary full-button" disabled={busy || loading}>{busy ? 'Kaydediliyor…' : 'Projeyi oluştur'} <ChevronRight size={16} /></button><span className="secure-note"><Shield size={14} /> Kayıt, kurum API’si üzerinden doğrulanır.</span></div><div className="info-note"><b><Activity size={16} /> Kayıt bilgisi</b><p>Başlık, açıklama, akademik yıl, kategori, durum ve öğrenciler proje kaydına eklenir.</p></div></aside></form></>
}

type ImportPreviewRow = { rowNumber: number; bilsemNo: string | null; firstName?: string; lastName?: string; resultTypes: string[]; message?: string; matchedAdvisorUserId?: string | null; resolutionRequired?: boolean; rowId?: string }
type ImportPreview = { batchId: string; totalRows: number; validRows: number; invalidRows: number; newStudentCount: number; continuingStudentCount: number; changedCount: number; warnings: unknown[]; results: ImportPreviewRow[] }
type ImportDbRow = { id: string; result: ImportPreviewRow; isSourceRow: boolean }
type TeacherOption = Pick<UserProfile, 'id' | 'name' | 'email' | 'isActive'>

function ExcelImport({ notify, refresh }: { notify: (message: string, type?: Toast['type']) => void; refresh: () => void }) {
  const [years, setYears] = useState<AcademicYear[]>([])
  const [yearId, setYearId] = useState('')
  const [teachers, setTeachers] = useState<TeacherOption[]>([])
  const [file, setFile] = useState<File | null>(null)
  const [batch, setBatch] = useState<ImportPreview | null>(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')

  useEffect(() => {
    apiRequest<AcademicYear[]>('/api/academic-years').then((ys) => {
      setYears(ys)
      setYearId((ys.find((y) => y.isCurrent) ?? ys[0])?.id ?? '')
    }).catch((e: unknown) => setError(e instanceof Error ? e.message : 'Akademik yıllar alınamadı.'))
    apiRequest<TeacherOption[]>('/api/admin/users?role=TEACHER&page=1&pageSize=100')
      .then((users) => setTeachers(users.filter((u) => u.isActive)))
      .catch(() => setTeachers([]))
  }, [])

  async function readImportRows(batchId: string) {
    const allRows: ImportDbRow[] = []
    let page = 1
    let totalPages: number
    do {
      const response = await fetch(`/api/imports/${batchId}/rows?page=${page}&pageSize=100`, { credentials: 'include' })
      const payload = await response.json() as { success: boolean; data?: ImportDbRow[]; pagination?: { totalPages: number }; error?: { message?: string } }
      if (!response.ok || !payload.success || !payload.data) throw new ApiError(payload.error?.message ?? 'Aktarım satırları alınamadı.', response.status)
      allRows.push(...payload.data)
      totalPages = payload.pagination?.totalPages ?? 1
      page += 1
    } while (page <= totalPages)
    return allRows
  }
  async function attachRowIds(previewData: ImportPreview) {
    const page = await readImportRows(previewData.batchId)
    const ids = new Map(page.filter((row) => row.isSourceRow).map((row) => [row.result.rowNumber, row.id]))
    setBatch({ ...previewData, results: previewData.results.map((row) => ({ ...row, rowId: ids.get(row.rowNumber) })) })
  }
  async function preview() {
    if (!file || !yearId) { setError('Excel dosyası ve akademik yıl seçin.'); return }
    if (!file.name.toLowerCase().endsWith('.xlsx')) { setError('Yalnızca .xlsx dosyası kabul edilir.'); return }
    setBusy(true); setError(''); setBatch(null)
    try {
      const params = new URLSearchParams({ academicYearId: yearId })
      const result = await apiRequest<ImportPreview>(`/api/imports/preview?${params}`, { method: 'POST', headers: { 'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'X-File-Name': encodeURIComponent(file.name) }, body: file })
      await attachRowIds(result)
    } catch (e) { setError(e instanceof Error ? e.message : 'Excel önizlemesi oluşturulamadı.') }
    finally { setBusy(false) }
  }
  async function resolveTeacher(row: ImportPreviewRow, advisorUserId: string) {
    if (!batch || !row.rowId) { setError('Bu satırın eşleştirme bilgisi yüklenmedi. Önizlemeyi yenileyin.'); return }
    if (!advisorUserId) { setError('Eşleştirme için etkin öğretmen hesabı seçin.'); return }
    setBusy(true); setError('')
    try {
      await apiRequest(`/api/imports/${batch.batchId}/rows/${row.rowId}/advisor`, { method: 'PATCH', body: JSON.stringify({ advisorUserId }) })
      const latest = await apiRequest<{ id: string; totalRows: number; validRows: number; invalidRows: number; newStudentCount: number; continuingStudentCount: number; changedCount: number }>(`/api/imports/${batch.batchId}`)
      const rows = await readImportRows(batch.batchId)
      setBatch({ ...batch, ...latest, batchId: latest.id, results: rows.filter((item) => item.isSourceRow).map((item) => ({ ...item.result, rowId: item.id })) })
    } catch (e) {
      const message = e instanceof ApiError && e.status === 404 ? 'Seçilen öğretmen etkin değil veya artık bulunamıyor. Güncel bir öğretmen seçin.' : e instanceof ApiError && e.status === 422 ? 'Bu satır artık eşleştirilemiyor. Önizlemeyi yenileyip kontrol edin.' : e instanceof Error ? e.message : 'Öğretmen eşleştirmesi kaydedilemedi.'
      setError(message)
    } finally { setBusy(false) }
  }
  async function commit() {
    if (!batch) return
    if (batch.invalidRows > 0) { setError('Önce tüm hatalı satırları ve zorunlu öğretmen eşleştirmelerini tamamlayın.'); return }
    setBusy(true)
    try { const result = await apiRequest<{ importedCount: number }>(`/api/imports/${batch.batchId}/commit`, { method: 'POST' }); notify(`${result.importedCount} öğrenci başarıyla aktarıldı.`); refresh(); setBatch(null); setFile(null) }
    catch (e) { setError(e instanceof Error ? e.message : 'Aktarım onaylanamadı.') }
    finally { setBusy(false) }
  }
  async function cancel() {
    if (!batch) return
    setBusy(true)
    try { await apiRequest(`/api/imports/${batch.batchId}/cancel`, { method: 'POST' }); setBatch(null); notify('Aktarım iptal edildi.') }
    catch (e) { setError(e instanceof Error ? e.message : 'Aktarım iptal edilemedi.') }
    finally { setBusy(false) }
  }

  return <><PageHeading eyebrow="ÖĞRENCİ YÖNETİMİ" title="Excel Aktarımı" description="Öğrenci listesini önizleyin, öğretmenleri eşleştirin ve aktarımı onaylayın." /><div className="import-layout"><div className="import-main"><section className="panel form-panel"><div className="form-section-title"><span>01</span><div><h3>Dosyanızı seçin</h3><p>Yalnızca .xlsx biçimi kabul edilir.</p></div></div><label className="field-label">Akademik yıl<select className="text-input" value={yearId} onChange={(e) => setYearId(e.target.value)}>{years.map((y) => <option value={y.id} key={y.id}>{y.name}</option>)}</select></label><label className="upload-zone"><Upload size={24} /><b>{file?.name ?? 'Excel dosyanızı buraya bırakın veya seçin'}</b><span>{file ? `${(file.size / 1024).toFixed(0)} KB · Seçildi` : 'XLSX · En fazla 4 MB'}</span><input type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" onChange={(e) => setFile(e.target.files?.[0] ?? null)} /></label>{error && <div className="form-error" role="alert">{error}</div>}<button className="button button-primary" disabled={busy || !file || !yearId} onClick={() => void preview()}>{busy ? 'İşleniyor…' : 'Dosyayı önizle'} <ChevronRight size={16} /></button></section>{batch && <section className="panel form-panel import-results"><div className="panel-heading"><div><h3>Önizleme sonucu</h3><p>Satırları kontrol edip zorunlu eşleştirmeleri tamamlayın.</p></div><span className="badge badge-blue">{batch.totalRows} kaynak satırı</span></div><div className="import-stat-row"><span><b>{batch.validRows}</b> Geçerli</span><span><b>{batch.invalidRows}</b> Kontrol gerekli</span><span><b>{batch.newStudentCount}</b> Yeni</span><span><b>{batch.continuingStudentCount}</b> Devam</span></div>{batch.results.filter((r) => r.rowNumber > 0).length ? <div className="table-wrap"><table><thead><tr><th>SATIR</th><th>BİLSEM NO</th><th>ÖĞRENCİ</th><th>SONUÇ / EŞLEŞTİRME</th></tr></thead><tbody>{batch.results.filter((r) => r.rowNumber > 0).map((r) => <tr key={r.rowNumber}><td>{r.rowNumber}</td><td className="mono">{r.bilsemNo ?? '—'}</td><td>{personName(r.firstName ?? '', r.lastName ?? '')}</td><td><span className={`badge ${r.resultTypes.includes('INVALID_RECORD') || r.resultTypes.includes('UNMATCHED_TEACHER') || r.resultTypes.includes('DUPLICATE_BILSEM_NO') ? 'badge-amber' : 'badge-green'}`}>{r.resultTypes.join(', ')}</span>{r.message && <small className="row-message">{r.message}</small>}{r.resolutionRequired && <div className="advisor-resolution"><select className="text-input" aria-label={`${r.firstName ?? ''} ${r.lastName ?? ''} danışman öğretmeni`} defaultValue=""><option value="">Etkin öğretmen seçin</option>{teachers.map((teacher) => <option key={teacher.id} value={teacher.id}>{teacher.name} · {teacher.email}</option>)}</select><button className="button button-secondary button-small" disabled={busy || !r.rowId} onClick={(event) => { const select = event.currentTarget.parentElement?.querySelector('select'); if (select) void resolveTeacher(r, select.value) }}>Eşleştir</button>{teachers.length === 0 && <small className="row-message">Etkin öğretmen hesabı bulunamadı. Önce öğretmen hesabı oluşturun.</small>}</div>}</td></tr>)}</tbody></table></div> : <EmptyState title="Aktarılabilir satır yok" message="Seçilen dosyada öğrenci satırı bulunamadı." />}<div className="import-actions"><button className="button button-secondary" disabled={busy} onClick={() => void cancel()}>Aktarımı iptal et</button><button className="button button-primary" disabled={busy || batch.validRows === 0 || batch.invalidRows > 0} onClick={() => void commit()}>{busy ? 'Onaylanıyor…' : 'Geçerli satırları aktar'} <Check size={16} /></button></div>{batch.invalidRows > 0 && <p className="inline-hint">{batch.invalidRows} satır kontrol bekliyor. Zorunlu öğretmen eşleştirmeleri ve diğer hatalar tamamlanmadan aktarım onaylanamaz.</p>}</section>}</div><aside className="import-aside"><div className="panel info-note"><b><FileSpreadsheet size={17} /> Excel şablon alanları</b><p>BİLSEM No, Ad, Soyad, Okul, Sınıf, Şube, Yetenek Alanı ve Danışman Öğretmen.</p><p>BİLSEM numarası rakamlardan oluşmalı. Güvenilir tam sayılar ve açık sıfır dolgulu biçimler kabul edilir; belirsiz hücreler önizlemede reddedilir.</p></div><div className="panel info-note"><b><Shield size={16} /> Güvenli aktarım</b><p>Dosya önce sunucuda ayrıştırılıp mevcut kayıtlarla karşılaştırılır. Öğrenciler yalnızca onayınızdan sonra kaydedilir.</p></div></aside></div></>
}

function UsersAdmin({ refreshKey, notify, user }: { refreshKey: number; notify: (message: string, type?: Toast['type']) => void; user: UserProfile }) {
  const [items, setItems] = useState<UserProfile[]>([]); const [search, setSearch] = useState(''); const [error, setError] = useState<unknown>(null); const [loading, setLoading] = useState(true); const [createOpen, setCreateOpen] = useState(false); const [createBusy, setCreateBusy] = useState(false); const [createError, setCreateError] = useState(''); const [teacherForm, setTeacherForm] = useState({ name: '', email: '' }); const [oneTimeCredential, setOneTimeCredential] = useState<{ name: string; email: string; password: string } | null>(null)
  const load = useCallback(() => { setLoading(true); apiRequest<UserProfile[]>(`/api/admin/users?page=1&pageSize=100${search.trim() ? `&search=${encodeURIComponent(search.trim())}` : ''}`).then(setItems).catch(setError).finally(() => setLoading(false)) }, [search])
  useEffect(() => { const timer = window.setTimeout(() => void load(), 0); return () => window.clearTimeout(timer) }, [load, refreshKey])
  async function update(id: string, body: { role?: Role; isActive?: boolean }) { try { await apiRequest(`/api/admin/users/${id}`, { method: 'PATCH', body: JSON.stringify(body) }); notify('Kullanıcı güncellendi.'); load() } catch (e) { notify(e instanceof Error ? e.message : 'Kullanıcı güncellenemedi.', 'error') } }
  async function createTeacher(e: FormEvent) { e.preventDefault(); setCreateBusy(true); setCreateError(''); setOneTimeCredential(null); try { const result = await apiRequest<{ user: { name: string; email: string }; temporaryPassword: string }>('/api/admin/teachers', { method: 'POST', body: JSON.stringify(teacherForm) }); setOneTimeCredential({ ...result.user, password: result.temporaryPassword }); setTeacherForm({ name: '', email: '' }); setCreateOpen(false); notify('Öğretmen hesabı oluşturuldu. Geçici parola bu ekranda yalnızca bir kez gösterilir.'); load() } catch (e) { setCreateError(e instanceof Error ? e.message : 'Öğretmen hesabı oluşturulamadı.') } finally { setCreateBusy(false) } }
  async function copyTemporaryPassword() { if (!oneTimeCredential) return; try { await navigator.clipboard.writeText(oneTimeCredential.password); notify('Geçici parola panoya kopyalandı.') } catch { notify('Kopyalama başarısız. Parolayı güvenli biçimde not edin.', 'error') } }
  return <><PageHeading eyebrow="KURUM AYARLARI" title="Kullanıcı Yönetimi" description="Hesap durumunu görüntüleyin; öğretmen hesapları oluşturun, rol ve erişimi yönetin." action={<div className="heading-count"><b>{items.length}</b><span>hesap</span></div>} />{oneTimeCredential && <section className="panel temporary-credential"><div><b>{oneTimeCredential.name} için geçici parola</b><p>{oneTimeCredential.email} · Bu parola yalnızca bu kez gösteriliyor. Öğretmen ilk girişte değiştirmeli.</p><code>{oneTimeCredential.password}</code></div><div className="temporary-actions"><button className="button button-secondary" onClick={() => void copyTemporaryPassword()}>Parolayı kopyala</button><button className="button button-primary" onClick={() => setOneTimeCredential(null)}>Güvenli biçimde aldım</button></div></section>}<section className="panel students-filter-panel"><label className="student-filter-search"><Search size={16}/><input aria-label="Kullanıcı ara" placeholder="Ad veya e-posta ile ara" value={search} onChange={(e) => setSearch(e.target.value)} /></label><button className="button button-primary" onClick={() => { setCreateOpen((v) => !v); setCreateError('') }}>{createOpen ? 'Formu kapat' : 'Öğretmen Ekle'}</button></section>{createOpen && <form className="panel teacher-create-form" onSubmit={(e) => void createTeacher(e)}><h3>Yeni öğretmen hesabı</h3><p>Sunucu güvenli bir geçici parola üretir. Hesap ilk girişte parola değişikliğini zorunlu kılar.</p><div className="form-two-col"><label className="field-label">Ad soyad<input className="text-input" required minLength={2} maxLength={200} value={teacherForm.name} onChange={(e) => setTeacherForm({ ...teacherForm, name: e.target.value })} /></label><label className="field-label">E-posta adresi<input className="text-input" type="email" required value={teacherForm.email} onChange={(e) => setTeacherForm({ ...teacherForm, email: e.target.value })} /></label></div>{createError && <div className="form-error" role="alert">{createError}</div>}<button className="button button-primary" disabled={createBusy}>{createBusy ? 'Hesap oluşturuluyor…' : 'Öğretmen hesabı oluştur'}</button></form>}<div className="user-reset-note user-reset-wide">E-posta sıfırlama bağlantısı etkin değil. Kurulumda e-posta sağlayıcısı yok ve Better Auth’un varsayılan token saklaması açık token kimliği içeriyor. Mevcut öğretmen parolası yönetici tarafından değiştirilemez.</div>{error ? <ErrorState error={error} retry={load} /> : loading ? <LoadingState /> : items.length ? <div className="panel table-panel"><div className="table-wrap"><table><thead><tr><th>KULLANICI</th><th>ROL</th><th>HESAP DURUMU</th><th>KAYIT TARİHİ</th><th>İŞLEMLER</th></tr></thead><tbody>{items.map((u) => <tr key={u.id}><td><div className="student-cell"><div className="student-avatar">{u.name.slice(0, 1)}</div><span><b>{u.name}</b><small>{u.email}</small></span></div></td><td><select className="table-select" value={u.role} onChange={(e) => void update(u.id, { role: e.target.value as Role })}><option value="TEACHER">Öğretmen</option><option value="ADMIN">Yönetici</option></select></td><td><span className={`badge ${u.isActive ? 'badge-green' : 'badge-amber'}`}>{u.isActive ? 'Etkin' : 'Pasif'}</span>{u.mustChangePassword && <small className="user-password-state">İlk parola değişikliği bekleniyor</small>}</td><td>{dateLabel(u.createdAt)}</td><td><button className={`button ${u.isActive ? 'button-secondary' : 'button-primary'} button-small`} disabled={u.id === user.id && u.isActive} onClick={() => void update(u.id, { isActive: !u.isActive })}>{u.id === user.id ? 'Kendi hesabınız' : u.isActive ? 'Erişimi kapat' : 'Etkinleştir'}</button></td></tr>)}</tbody></table></div></div> : <div className="panel"><EmptyState title="Kullanıcı bulunamadı" message="Aramanızı değiştirin veya öğretmen hesabı oluşturun." /></div>}</>
}
function AcademicYears({ refreshKey, notify }: { refreshKey: number; notify: (message: string, type?: Toast['type']) => void }) { const [items, setItems] = useState<AcademicYear[]>([]); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const [form, setForm] = useState({ name: '', startsOn: '', endsOn: '', isCurrent: false }); const load = useCallback(() => { apiRequest<AcademicYear[]>('/api/academic-years').then(setItems).catch((e) => setError(e.message)) }, []); useEffect(() => { const timer = window.setTimeout(() => load(), 0); return () => window.clearTimeout(timer) }, [load, refreshKey]); async function submit(e: FormEvent) { e.preventDefault(); const parsed = z.object({ name: z.string().trim().min(1, 'Yıl adı zorunlu.'), startsOn: z.iso.date(), endsOn: z.iso.date() }).safeParse(form); if (!parsed.success) { setError(parsed.error.issues[0]?.message ?? 'Bilgileri kontrol edin.'); return }; setBusy(true); setError(''); try { await apiRequest('/api/academic-years', { method: 'POST', body: JSON.stringify(form) }); setForm({ name: '', startsOn: '', endsOn: '', isCurrent: false }); notify('Akademik yıl oluşturuldu.'); load() } catch (e) { setError(e instanceof Error ? e.message : 'Akademik yıl eklenemedi.') } finally { setBusy(false) } } return <><PageHeading eyebrow="KURUM AYARLARI" title="Akademik Yıllar" description="Öğrenci ve proje kayıtlarının bağlandığı akademik dönemleri yönetin." /><div className="year-layout"><section className="panel form-panel"><div className="form-section-title"><span>01</span><div><h3>Yeni akademik yıl</h3><p>Başlangıç ve bitiş tarihlerini girin.</p></div></div><form onSubmit={(e) => void submit(e)}><label className="field-label">Akademik yıl adı<input className="text-input" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="2026–2027" /></label><div className="form-two-col"><label className="field-label">Başlangıç tarihi<input className="text-input" type="date" value={form.startsOn} onChange={(e) => setForm({ ...form, startsOn: e.target.value })} /></label><label className="field-label">Bitiş tarihi<input className="text-input" type="date" value={form.endsOn} onChange={(e) => setForm({ ...form, endsOn: e.target.value })} /></label></div><label className="checkbox-line"><input type="checkbox" checked={form.isCurrent} onChange={(e) => setForm({ ...form, isCurrent: e.target.checked })} /> Bu yılı güncel akademik yıl yap</label>{error && <div className="form-error" role="alert">{error}</div>}<button className="button button-primary" disabled={busy}>{busy ? 'Kaydediliyor…' : 'Akademik yılı ekle'} <Plus size={16} /></button></form></section><section className="panel"><div className="panel-heading"><div><h3>Tanımlı yıllar</h3><p>{items.length} akademik dönem</p></div></div>{items.length ? <div className="year-list">{items.map((y) => <div className="year-row" key={y.id}><span className="year-icon"><CalendarDays size={18} /></span><span><b>{y.name}</b><small>{dateLabel(y.startsOn)} — {dateLabel(y.endsOn)}</small></span>{y.isCurrent && <span className="badge badge-green">Güncel</span>}</div>)}</div> : <EmptyState title="Akademik yıl yok" message="Öğrenci kaydı için önce bir akademik yıl oluşturun." />}</section></div></> }

function Notifications({ refreshKey }: { refreshKey: number }) { const [items, setItems] = useState<Array<{ id: string; title: string; message: string; isRead: boolean; createdAt: string }>>([]); const [error, setError] = useState<unknown>(null); const load = useCallback(() => { apiRequest<Array<{ id: string; title: string; message: string; isRead: boolean; createdAt: string }>>('/api/notifications?page=1&pageSize=100').then(setItems).catch(setError) }, []); useEffect(() => { const timer = window.setTimeout(() => load(), 0); return () => window.clearTimeout(timer) }, [load, refreshKey]); async function mark(id: string) { try { await apiRequest(`/api/notifications/${id}/read`, { method: 'PATCH' }); load() } catch (e) { setError(e) } } return <><PageHeading eyebrow="HESAP" title="Bildirimler" description="Kurum hesabınıza gönderilen güncellemeler." />{error ? <ErrorState error={error} retry={load} /> : items.length ? <div className="panel notification-list">{items.map((n) => <article className={`notification-row ${n.isRead ? '' : 'notification-unread'}`} key={n.id}><span className="notification-icon"><Bell size={17} /></span><div><b>{n.title}</b><p>{n.message}</p><small>{dateLabel(n.createdAt)}</small></div>{!n.isRead && <button className="text-button" onClick={() => void mark(n.id)}>Okundu işaretle</button>}</article>)}</div> : <div className="panel"><EmptyState title="Yeni bildirim yok" message="Öğrenci ve proje çalışmalarınızla ilgili güncellemeler burada görünür." /></div>}</> }
